from __future__ import absolute_import

import os

from robot.api import logger
import re
import json

from collections import defaultdict

from hran_radio.exceptions import ConnectionError
from hran_radio.radio_power import RadioPower
from .radio_classes.fault import Fault


class FaultsDiagnostic(object):
    def __init__(self):
        super(FaultsDiagnostic, self).__init__()
        self.port = 2323
        self.host = None
        self.LTX = "LTX"
        self.TX = "TX"
        self.RX = "RX"
        self._msm_ip = "192.168.255.1"

    def connect_sendfault_diagnostic(self, radio_ip, module_ip):
        """
        Setup keyword Send Fault

        | **Author:** jaroslaw.piszczala@nokia.com
        | **Maintainer:** jaroslaw.piszczala@nokia.com
        | **Released with version:** 2.6.0

        .. warning::
            Supported radio types are: RadioWMP and RadioGAIA

        | **Full description:**
        | Setups connection for Fault Diagnostics keywords

        +------------------+------+-------------------------------------------------------------------------+
        | Input Parameters | Man. | Description                                                             |
        +==================+======+=========================================================================+
        | radio_ip         | Yes  | ip address of radio module from which sendFault help will be gathered   |
        +------------------+------+-------------------------------------------------------------------------+
        | module_ip        | Yes  | ip address of master system module which radio module is connected with |
        +------------------+------+-------------------------------------------------------------------------+
        """
        self.radio = Fault(radio_ip, module_ip, self._msm_ip)

    def find_resources_ids_in_help_output(self):
        """
        Find resources ids is help output

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** jaroslaw.piszczala@nokia.com

        | **Full description:**
        | Retrieves help output for `sendFault` function via telnet and
        | creates a map of resource types and its respective ids.
        | Supports rel3 and rel4

        | **Return value:**
        | map of resource types and respective resource ids
        """
        resources = defaultdict(list)
        command = "sendFault"
        help_output = self.radio.run_radio_command(command)

        patterns = {
            self.LTX: re.compile(r"module\s+=\s+([\d]+)"),
            self.RX: re.compile(r"antenna.*?\(RX\)\s+=\s([\d]+)"),
            self.TX: re.compile(r"antenna.*?\(TX\)\s+=\s([\d]+)"),
        }

        antenna_line_regex = re.compile(r"(antenna\d[a|b])\s\((TX|RX)\)\s+=\s([\d]+)")
        for line in help_output.split("\n"):
            antenna_line = re.search(antenna_line_regex, line)
            if antenna_line:
                antenna, direction, resource = antenna_line.groups()
                resources[antenna].append((direction, resource))
            for resource_type, pattern in patterns.items():
                match = re.search(pattern, line)
                if match:
                    resource_id = match.group(1)
                    resources[resource_type].append(resource_id)

        logger.debug(
            "Using sources mapping: {mapping}".format(
                mapping=", ".join(
                    "{} -> {}".format(*item) for item in sorted(resources.items())
                )
            )
        )
        return resources

    def send_fault(self, fault_id, tx_number):
        """
        Send fault

        | **Author:** jaroslaw.piszczala@nokia.com
        | **Maintainer:** jaroslaw.piszczala@nokia.com
        | **Released with version:** 2.6.0

        .. warning::
            Supported radio types are: RadioWMP and RadioGAIA

        | **Full description:**
        | Run `sendFault` function via telnet with given fault_id and tx_number
        | Command format `sendFault {fault_id} {tx_number} 0 0 0 0`
        | Supports rel3 and rel4

        +------------------+------+-------------+
        | Input Parameters | Man. | Description |
        +==================+======+=============+
        | fault_id         | Yes  | Fault ID    |
        +------------------+------+-------------+
        | TX_number        | Yes  | TX number   |
        +------------------+------+-------------+
        """
        command = "sendFault {} {} 0 0 0 0".format(fault_id, tx_number)
        self.radio.run_radio_command(command)


class FaultsDiagnostic5_1(RadioPower):
    def __init__(self):
        super(FaultsDiagnostic5_1, self).__init__()
        self._msm_ip = "192.168.255.1"

    def send_fault_51(self, radio_ip, module_ip, radio_type, fault_id):
        """
        Send fault 5.1

        | **Author:** marcin.jezewski@nokia.com
        | **Maintainer:** rafal.ozga@nokia.com
        | **Released with version:** 2.22.0

        .. warning::
            Supported radio types are only 5.1 types

        | **Full description:**
        | To inject fault into RM5.1 create object FaultDiagnostic5_1()
        | and then send desired fault using this method
        |
        | Supports rel3 and rel4

        +------------------+------+----------------+
        | Input Parameters | Man. | Description    |
        +==================+======+================+
        | radio_ip         | Yes  | RM ip address  |
        +------------------+------+----------------+
        | module_ip        | Yes  | SM ip address  |
        +------------------+------+----------------+
        | radio_type       | Yes  | RM type name   |
        +------------------+------+----------------+
        | fault_id         | Yes  | Fault number   |
        +------------------+------+----------------+

        Supported faults:
        +----------------------------------+--------------------+
        | Fault name                       | Fault ID           |
        +==================================+====================+
        | EFaultId_FilterInputPowerMissing | 1910               |
        +----------------------------------+--------------------+

        """
        self.esm_ip = module_ip
        self.radio_ip = radio_ip
        self.radio = self._set_up_radio(radio_ip, radio_type, module_ip)
        faults = {"1910": self.EFaultId_FilterInputPowerMissing()}

        faults[fault_id]

    def EFaultId_FilterInputPowerMissing(self):
        if self.radio._sm_ip != '192.168.255.1':
            self._inject_fault_with_esm_connection()
        else:
            self._inject_fault_on_radio_without_esm()

    def _validate_creating_ConfigAccess(self, response):
        parser = re.search(r'(done ok|Path already taken)', response)
        if parser:
            return True
        return False

    def _validate_configuration_update(self, response):
        parser = re.search(r'done ok', response)
        if parser:
            return True
        return False

    def _inject_fault_on_radio_without_esm(self):
        self._create_config_access()
        last_path = self._get_last_path()
        self.radio.radio_connection.ommit_frmon = True
        for path_no in range(1, last_path):
            readed_json = self.radio.run_radio_command("cat /ram/calibration_dlpath{}.json".format(path_no))
            dumped = json.loads(readed_json)
            for element in dumped["txVswr"]:
                element["offset_filter_mB"] = 0
            self.radio.run_radio_command(
                "rm /ram/calibration_dlpath{}.json".format(path_no))

            with open("calibration_dlpath{}.json".format(path_no), "w+") as opened_file:
                opened_file.write(json.dumps(dumped))
            self.radio.radio_connection.send_file_to_msm("calibration_dlpath{}.json".format(path_no),
                                                         "/user/toor4nsn/calibration_dlpath{}.json".format(path_no))

            os.remove("calibration_dlpath{}.json".format(path_no))
            self.radio.radio_connection.execute_command_on_msm = True

            self.radio.run_radio_command(
                "scp /user/toor4nsn/calibration_dlpath{}.json root@{}:/ram/calibration_dlpath{}.json".format(path_no,
                                                                                                             self.radio_ip,
                                                                                                             path_no))
            self.radio.radio_connection.execute_command_on_msm = False
            self.radio.radio_connection.remove_file_from_msm("/user/toor4nsn/calibration_dlpath{}.json".format(path_no))

        self.radio.radio_connection.ommit_frmon = False
        for path_no in range(1, last_path):
            response = self.radio.run_radio_command(
                '/ca action store DECODED "unit/calibration_dlpath{}.bin" "/ram/calibration_dlpath{}.json"'.format(
                    path_no, path_no))
            logger.debug(response)
        response = self.radio.run_radio_command('/ca action update')
        logger.debug(response)
        if not self._validate_configuration_update(response):
            raise ConnectionError
        logger.info("New jsons injected, restart carrier for activating fault.")

    def _inject_fault_with_esm_connection(self):
        self._create_config_access()
        last_path = self._get_last_path()
        self.radio.radio_connection.ommit_frmon = True
        for path_no in range(1, last_path):
            readed_json = self.radio.run_radio_command("cat /ram/calibration_dlpath{}.json".format(path_no))
            dumped = json.loads(readed_json)
            for element in dumped["txVswr"]:
                element["offset_filter_mB"] = 0
            self.radio.run_radio_command(
                "rm /ram/calibration_dlpath{}.json".format(path_no))

            with open("calibration_dlpath{}.json".format(path_no), "w+") as opened_file:
                opened_file.write(json.dumps(dumped))
            self.radio.radio_connection.send_file_to_esm('calibration_dlpath{}.json'.format(path_no),
                                                         '/user/toor4nsn/calibration_dlpath{}.json'.format(path_no))
            os.remove("calibration_dlpath{}.json".format(path_no))
            self.radio.radio_connection.execute_command_on_msm = True
            response = self.radio.run_radio_command(
                "scp /user/toor4nsn/calibration_dlpath{}.json root@{}:/ram/calibration_dlpath{}.json".format(path_no,
                                                                                                             self.radio_ip,
                                                                                                             path_no))
            logger.debug(response)
            self.radio.radio_connection.execute_command_on_msm = False
            self.radio.radio_connection.run_command_on_esm(
                "rm /user/toor4nsn/calibration_dlpath{}.json".format(path_no))
        self.radio.radio_connection.ommit_frmon = False
        for path_no in range(1, last_path):
            response = self.radio.run_radio_command(
                '/ca action store DECODED "unit/calibration_dlpath{}.bin" "/ram/calibration_dlpath{}.json"'.format(
                    path_no, path_no))
            logger.debug(response)
        response = self.radio.run_radio_command('/ca action update')
        logger.debug(response)
        if not self._validate_configuration_update(response):
            raise ConnectionError
        logger.info("New jsons injected, restart carrier for activating fault.")

    def _create_config_access(self):
        response = self.radio.run_radio_command('/ action create ConfigAccess /ca /module\r')
        if not self._validate_creating_ConfigAccess(response):
            raise ConnectionError

    def _get_last_path(self):
        MAX_PATH = 24
        for path_no in range(1, MAX_PATH):
            response = self.radio.run_radio_command(
                '/ca action fetch DECODED "unit/calibration_dlpath{}.bin" "/ram/calibration_dlpath{}.json"'.format(
                    path_no, path_no))
            logger.debug(response)

            if re.search(r'No such file or directory', response):
                last_path = path_no
                logger.debug("Last path: {}".format(last_path))
                return last_path
